package id.hawx.astro.goose;

import android.os.Bundle;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;

import id.hawx.astro.R;

import java.io.File;

/**
 * Simple WebView to render HTML visualizations generated by Ghost.
 * Opened from the Files menu when tapping a .html file.
 */
public class GhostVizActivity extends AppCompatActivity {

    public static final String EXTRA_PATH = "path";
    /** Port server webui (bila > 0, activity ini milik mode webui:
     *  finish -> matikan servernya). -1 = halaman web biasa. */
    public static final String EXTRA_WEBUI_PORT = "webui_port";

    // Registry jendela web terbuka (buat "Kill" dari ikon desktop):
    // satu activity per berkas, ditutup lewat closeByPath.
    private static final java.util.Map<String,
            java.lang.ref.WeakReference<GhostVizActivity>> sOpen =
            new java.util.HashMap<>();

    public static boolean closeByPath(String path) {
        java.lang.ref.WeakReference<GhostVizActivity> r = sOpen.get(path);
        GhostVizActivity a = r != null ? r.get() : null;
        if (a == null || a.isFinishing()) return false;
        a.finish();
        return true;
    }
    public static final String EXTRA_TITLE = "title";

    // WebView halaman — field (bukan lokal onCreate) supaya
    // onBackPressed bisa memeriksa history-nya.
    private WebView webView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_ghost_viz);

        Toolbar toolbar = findViewById(R.id.viz_toolbar);
        setSupportActionBar(toolbar);
        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        }

        String path = getIntent().getStringExtra(EXTRA_PATH);
        if (path != null) sOpen.put(path, new java.lang.ref.WeakReference<>(this));
        String title = getIntent().getStringExtra(EXTRA_TITLE);
        if (title != null && getSupportActionBar() != null) {
            getSupportActionBar().setTitle(title);
        }

        webView = findViewById(R.id.viz_webview);
        WebSettings ws = webView.getSettings();
        ws.setJavaScriptEnabled(true);
        ws.setDomStorageEnabled(true);
        ws.setAllowFileAccess(true);
        ws.setMediaPlaybackRequiresUserGesture(false);
        ws.setBuiltInZoomControls(true);
        ws.setDisplayZoomControls(false);
        ws.setSupportZoom(true);
        webView.setWebViewClient(new WebViewClient());
        // Fondasi tools WebView: bridge perintah chroot buat halaman lokal.
        webView.addJavascriptInterface(
                new ToolsBridge(new id.hawx.astro.utils.Core(this), webView),
                "AstroBridge");

        if (path != null) {
            if (path.startsWith("http://") || path.startsWith("https://")) {
                // Mode webui: URL server localhost — load langsung,
                // bukan sebagai path berkas.
                webView.loadUrl(path);
            } else {
                File f = new File(path);
                if (f.exists()) {
                    webView.loadUrl("file://" + f.getAbsolutePath());
                }
            }
        }
    }

    @Override
    protected void onDestroy() {
        String path = getIntent().getStringExtra(EXTRA_PATH);
        if (path != null) {
            java.lang.ref.WeakReference<GhostVizActivity> r = sOpen.get(path);
            if (r != null && r.get() == this) sOpen.remove(path);
        }
        // Fullscreen tidak punya hide (—): tutup = kill server.
        // isFinishing() = back / closeByPath; rotasi (recreate)
        // TIDAK mematikan server (activity tidak finishing).
        int webuiPort = getIntent().getIntExtra(EXTRA_WEBUI_PORT, -1);
        if (webuiPort > 0 && isFinishing()) {
            id.hawx.astro.x11.WebUiLauncher.killServer(this, webuiPort);
        }
        super.onDestroy();
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }

    /**
     * Back sistem di webview fullscreen: mundur satu history bila
     * ada, kalau tidak berperilaku persis seperti sebelumnya
     * (finish — untuk webui itu jalur kill server yang sudah ada
     * di onDestroy; tidak diubah).
     */
    @Override
    public void onBackPressed() {
        if (webView != null && webView.canGoBack()) {
            webView.goBack();
        } else {
            super.onBackPressed();
        }
    }
}
